mapper.select:
SELECT 
  FROM pay21_rate
 WHERE pay21_rate_cd LIKE #{rateCode}

mapper.update:
UPDATE pay21_rate
   SET pay21_rate_cd    = #{req.rateCode},
       pay21_start_date = #{req.startDate},
       pay21_apply_rate = #{req.applyRate},
       pay21_note       = #{req.note}
 WHERE pay21_rate_id = #{req.rateId}

mapper.delete:
DELETE FROM pay21_rate
 WHERE pay21_rate_id IN
#{id}
